import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layer_norm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(const float* __restrict__ x,
                                   const float* __restrict__ weight,
                                   const float* __restrict__ bias,
                                   float* __restrict__ out,
                                   int N, float eps) {
    int batch = blockIdx.x;
    const float* x_ptr = x + (size_t)batch * N;
    float* out_ptr = out + (size_t)batch * N;
    extern __shared__ double sdata[];
    double* swarp_sum = sdata;
    double* swarp_sqsum = sdata + (blockDim.x / 32);
    double sum = 0.0, sqsum = 0.0;
    int N4 = N / 4;
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr);
    for (int i = threadIdx.x; i < N4; i += blockDim.x) {
        float4 v4 = x_ptr4[i];
        double v0 = (double)v4.x;
        double v1 = (double)v4.y;
        double v2 = (double)v4.z;
        double v3 = (double)v4.w;
        sum += v0 + v1 + v2 + v3;
        sqsum += v0 * v0 + v1 * v1 + v2 * v2 + v3 * v3;
    }
    for (int i = N4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
        double v = (double)x_ptr[i];
        sum += v;
        sqsum += v * v;
    }
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;
    if (lane_id == 0) {
        swarp_sum[warp_id] = sum;
        swarp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    int num_warps = blockDim.x / 32;
    if (warp_id == 0) {
        sum = (lane_id < num_warps) ? swarp_sum[lane_id] : 0.0;
        sqsum = (lane_id < num_warps) ? swarp_sqsum[lane_id] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
            sqsum += __shfl_down_sync(mask, sqsum, offset);
        }
    }
    __shared__ float mean;
    __shared__ float inv_std;
    if (threadIdx.x == 0) {
        double d_mean = sum / N;
        double d_var = sqsum / N - d_mean * d_mean;
        mean = (float)d_mean;
        inv_std = (float)rsqrt(d_var + (double)eps);
    }
    __syncthreads();
    const float4* w_ptr4 = reinterpret_cast<const float4*>(weight);
    const float4* b_ptr4 = reinterpret_cast<const float4*>(bias);
    float4* out_ptr4 = reinterpret_cast<float4*>(out_ptr);
    for (int i = threadIdx.x; i < N4; i += blockDim.x) {
        float4 v4 = x_ptr4[i];
        float4 w4 = w_ptr4[i];
        float4 b4 = b_ptr4[i];
        float4 r;
        r.x = (v4.x - mean) * inv_std * w4.x + b4.x;
        r.y = (v4.y - mean) * inv_std * w4.y + b4.y;
        r.z = (v4.z - mean) * inv_std * w4.z + b4.z;
        r.w = (v4.w - mean) * inv_std * w4.w + b4.w;
        out_ptr4[i] = r;
    }
    for (int i = N4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
        float v = x_ptr[i];
        out_ptr[i] = (v - mean) * inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    int64_t batch_size = 1;
    int64_t norm_numel = weight.numel();
    int64_t total = x_contig.numel();
    batch_size = total / norm_numel;

    const int threads = 1024;
    const int blocks = (int)batch_size;
    size_t shared_mem = 2 * (threads / 32) * sizeof(double);

    layer_norm_kernel<<<blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)norm_numel,
        (float)eps
    );

    return out;
}
"""

layer_norm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layer_norm_module = load_inline(
    name="layer_norm_module",
    cpp_sources=layer_norm_cpp_source,
    cuda_sources=layer_norm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.layer_norm_op = layer_norm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return self.layer_norm_op.layer_norm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256

def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2)
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x]

def get_init_inputs():
    return [(features, dim1, dim2)]

